{
  "items": [
    {
      "title": "German Socio-Economic Panel (SOEP-Core)",
      "url_or_doi": "https://doi.org/10.5684/soep.core.v41r",
      "justification": "SOEP-Core is a long-running, representative multi-cohort panel study of private households in Germany conducted by DIW Berlin. It tracks labor force participation, employment histories, wages, and working conditions annually across the 2010s and 2020s."
    },
    {
      "title": "Sample of Integrated Labour Market Biographies (SIAB)",
      "url_or_doi": "https://doi.org/10.5164/IAB.FDZD.2101.de.v1",
      "justification": "Provided by the Research Data Centre (FDZ) of the German Federal Employment Agency at the IAB, SIAB is a 2% sample of individual employment and labor market histories in Germany, covering employment subject to social security, marginal part-time work, and benefit receipt through the 2010s and 2020s."
    },
    {
      "title": "IAB Establishment Panel (IAB-BP)",
      "url_or_doi": "https://doi.org/10.5164/IAB.IABBP9320.de.en.v1",
      "justification": "An annual nationwide representative employer survey conducted by the IAB since 1993, providing comprehensive longitudinal data on labor demand, establishment-level employment trends, worker turnover, and wages across Germany during the 2010s and 2020s."
    },
    {
      "title": "Establishment History Panel (BHP)",
      "url_or_doi": "https://doi.org/10.5164/IAB.BHP7524.de.en.v1",
      "justification": "Aggregated administrative dataset from the IAB containing annual establishment-level data for all business units in Germany with social security-liable employees, recording employment structure, worker flows, and wage medians through the 2010s and 2020s."
    }
  ]
}
